// Writes `src/rpc-get-paths.generated.ts` from the `rpcProcedure` declarations of `webContract`.
// Run with `bun run generate` in packages/web-contract after adding, removing or re-declaring a
// procedure; `src/rpc-get-paths.test.ts` fails until the table matches the contract again.
import { webContract } from '../src/contract';
import { rpcGetPathsFor } from '../src/rpc-procedure-table';

export const renderRpcGetPathsModule = (paths: readonly string[]): string =>
  [
    '// Generated by `bun run generate` in packages/web-contract from the `rpcProcedure` declarations of',
    '// `webContract`. Do not edit: `rpc-get-paths.test.ts` fails when it disagrees with the contract.',
    '',
    '/**',
    ' * The procedures the browser calls with GET, as `/`-joined router paths; every other procedure is a',
    ' * POST. The browser imports this table instead of the contract, so choosing a method adds no schema',
    ' * to its bundle (ADR 0076).',
    ' */',
    'export const rpcGetPaths: readonly string[] = [',
    ...paths.map((path) => `  '${path}',`),
    '];',
    '',
  ].join('\n');

if (import.meta.main) {
  const target = new URL('../src/rpc-get-paths.generated.ts', import.meta.url);
  await Bun.write(target, renderRpcGetPathsModule(rpcGetPathsFor(webContract)));
  console.log(`Wrote ${target.pathname}`);
}
